import { operation, resource } from "@tinker/core";
import type { Operation } from "@tinker/core";

import { database, drizzleOrm } from "~/components/database/index.server";
import { raise } from "~/components/errors";
import { backendStop, requestStop, startRequests } from "~/components/requests";
import { notifications, streamCursor, streamRequest, event } from "~/components/sync/index.server";
import type { Stream } from "~/components/sync/index.server";

import { liveAccount } from "./auth.server";

/** One replay page owns its database read and encoded bytes. */
const readFrame = operation({
  label: "sync.frame",
  depends: { database, orm: drizzleOrm },
  run: async (
    { database, orm },
    { input }: Operation.Ctx<Stream.Cursor>,
  ): Promise<Stream.Frame> => {
    const { and, or, eq, gt, asc } = orm;
    const next = { public: input.public, private: input.private ? { ...input.private } : null };
    const rows = await database
      .select()
      .from(event)
      .where(
        or(
          and(eq(event.stream, "public"), gt(event.revision, next.public)),
          next.private
            ? and(
                eq(event.stream, next.private.accountId),
                gt(event.revision, next.private.revision),
              )
            : undefined,
        ),
      )
      .orderBy(asc(event.stream), asc(event.revision))
      .limit(100);

    for (const row of rows) {
      if (row.stream === "public") next.public = row.revision;
      else if (next.private) next.private.revision = row.revision;
    }

    const encoder = new TextEncoder();
    return {
      cursor: next,
      count: rows.length,
      bytes: rows.length
        ? encoder.encode(
            `event: changes\nid: ${JSON.stringify(next)}\ndata: ${JSON.stringify({ kind: "changes", events: rows })}\n\n`,
          )
        : new Uint8Array(),
    };
  },
});

/** The request owns one subscription, identity lease, and shared account recheck. */
const streamLease = resource({
  label: "sync.streamLease",
  target: "session",
  depends: { notifications, account: liveAccount.controller, backendStop, requestStop },
  factory: async (
    { notifications, account, backendStop, requestStop },
    { signal: cleanup, defer, clock },
  ) => {
    const stop = new AbortController();
    const signal = AbortSignal.any([stop.signal, backendStop, requestStop, cleanup]);
    const done = Symbol("sync.waitDone");
    let subscription: Awaited<ReturnType<typeof notifications.subscribe>> | undefined;
    let expectedAccount: string | null = null;
    let deadline = Infinity;
    let changed = false;
    let checking: Promise<number> | undefined;

    defer(() => lease.close());

    const lease = {
      signal,
      get changed() {
        return changed;
      },
      async open(initial: Stream.Cursor) {
        expectedAccount = initial.private?.accountId ?? null;
        subscription = await notifications.subscribe(stop.abort.bind(stop, done), expectedAccount);
        if (signal.aborted) {
          notifications.close(subscription);
          raise("Cancelled", {});
        }

        const current = await account.run();
        if (initial.private && initial.private.accountId !== current) raise("StreamDenied", {});
        deadline = clock.currentTimeMillis() + 30_000;
        if (current !== expectedAccount) subscription.stale = true;
      },
      async check(): Promise<number> {
        if (!subscription) raise("StreamDisconnected", {});
        if (notifications.ended(subscription) || clock.currentTimeMillis() >= deadline) {
          lease.close();
          return notifications.revision();
        }

        if (checking) return checking;
        if (!subscription.stale) return notifications.revision();
        subscription.stale = false;
        checking = account
          .run()
          .then((current) => {
            if (!signal.aborted && current !== expectedAccount) {
              changed = true;
              stop.abort(done);
            }
            return notifications.revision();
          })
          .finally(() => {
            checking = undefined;
          });
        return checking;
      },
      async wait(after: number) {
        await lease.check();
        if (signal.aborted) return false;
        if (!subscription) raise("StreamDisconnected", {});

        const heartbeat = await notifications.wait(subscription, after, deadline);
        await lease.check();
        return heartbeat;
      },
      revision() {
        return notifications.revision();
      },
      close() {
        if (subscription) notifications.close(subscription);
        stop.abort(done);
      },
    };
    return lease;
  },
});

type Read =
  | { kind: "ended" }
  | { kind: "idle"; wake: number }
  | { kind: "frame"; bytes: Uint8Array };

/** One request advances its cursor; cached frame values are never changed or handed to the body. */
const streamReader = resource({
  label: "sync.streamReader",
  target: "session",
  depends: { lease: streamLease, notifications, requests: startRequests },
  factory: async ({ lease, notifications, requests }) => {
    const frame = requests.scope.controller(readFrame);
    let cursor: Stream.Cursor = { public: 0, private: null };
    let afterWake = -1;
    return {
      async open(initial: Stream.Cursor) {
        await lease.open(initial);
        cursor = { ...initial, private: initial.private ? { ...initial.private } : null };
      },
      async read(): Promise<Read> {
        const wake = await lease.check();
        if (lease.signal.aborted) return { kind: "ended" };
        if (wake === afterWake) return { kind: "idle", wake };
        const privateKey = cursor.private
          ? `${cursor.private.accountId.length}:${cursor.private.accountId}:${cursor.private.revision}`
          : "-";
        const next = await notifications.share(
          `${cursor.public}:${privateKey}`,
          frame.settle.bind(frame),
          cursor,
        );
        await lease.check();
        if (lease.signal.aborted) return { kind: "ended" };

        if (!next.count) {
          afterWake = wake;
          return { kind: "idle", wake };
        }
        if (next.count < 100) afterWake = wake;
        cursor = next.cursor;
        return { kind: "frame", bytes: next.bytes.slice() };
      },
    };
  },
});

/** The request owns pulls and its independent watch loop, even when the client stops reading. */
export const eventStream = resource({
  label: "sync.stream",
  target: "session",
  depends: { lease: streamLease, reader: streamReader },
  factory: async ({ lease, reader }, { defer }) => {
    const encoder = new TextEncoder();
    const accountChange = encoder.encode('event: account\ndata: {"kind":"account-change"}\n\n');
    let output: ReadableStreamDefaultController<Uint8Array> | undefined;
    let ended = false;
    let watching: Promise<void> | undefined;
    let activity = Promise.withResolvers<boolean>();

    const close = () => {
      if (ended) return;
      ended = true;
      activity.resolve(false);

      if (lease.changed) output?.enqueue(accountChange.slice());
      output?.close();
      lease.close();
    };

    lease.signal.addEventListener("abort", close, { once: true });
    defer(async () => {
      close();
      lease.signal.removeEventListener("abort", close);
      await watching;
    });

    return {
      async open(initial: Stream.Cursor) {
        await reader.open(initial);
        let greeted = false;
        return new ReadableStream<Uint8Array>(
          {
            start(controller) {
              output = controller;
              if (ended) {
                controller.close();
                return;
              }
              watching = Promise.resolve()
                .then(async () => {
                  while (!ended) {
                    const wake = await lease.check();
                    if (ended) return;
                    const heartbeat = await lease.wait(wake);

                    const waiting = activity;
                    activity = Promise.withResolvers<boolean>();
                    waiting.resolve(heartbeat);
                  }
                })
                .catch((error) => {
                  if (lease.signal.aborted) {
                    close();
                    return;
                  }
                  ended = true;
                  activity.resolve(false);
                  output?.error(error);
                  lease.close();
                });
            },
            pull(controller) {
              return Promise.resolve()
                .then(async () => {
                  while (!ended) {
                    const awake = activity.promise;
                    const frame = await reader.read();
                    if (frame.kind === "ended") return;
                    if (frame.kind === "frame") {
                      controller.enqueue(frame.bytes);
                      return;
                    }
                    if (lease.revision() !== frame.wake) continue;
                    if (!greeted) {
                      greeted = true;
                      controller.enqueue(encoder.encode(": connected\n\n"));
                      return;
                    }

                    const heartbeat = await awake;
                    await lease.check();
                    if (!heartbeat) continue;
                    if (!ended) controller.enqueue(encoder.encode(": heartbeat\n\n"));
                    return;
                  }
                })
                .catch((error) => {
                  if (lease.signal.aborted) {
                    close();
                    return;
                  }
                  ended = true;
                  activity.resolve(false);
                  output?.error(error);
                  lease.close();
                });
            },
            cancel() {
              output = undefined;
              close();
            },
          },
          { highWaterMark: 0 },
        );
      },
    };
  },
});

/** A reconnect cursor wins over the query cursor; both are checked before opening the body. */
export const openSync = operation({
  label: "sync.open",
  input: (raw: unknown) => {
    const request = streamRequest.parse(raw);
    const supplied = request.lastEventId || new URLSearchParams(request.search).get("cursor");
    return {
      cursor: streamCursor.parse(supplied ? JSON.parse(supplied) : { public: 0, private: null }),
    };
  },
  depends: { stream: eventStream },
  run: async ({ stream }, { input }) => stream.open(input.cursor),
});

import { extension, operation, resource, tag } from "@tinker/core";
import type { PoolClient } from "pg";
import { z } from "zod";

import { fail } from "~/components/errors";

import { leaseFrom } from "./lease.server";
import { postgres, drizzlePostgres, drizzlePgCore, drizzleMigrator, drizzleOrm } from "./modules";
import type { Database } from "./types";

/** Where Postgres is. */
export const databaseUrl = tag<URL>({ label: "database.url", parse: z.instanceof(URL) });

/** Worker-only stop cancels startup and pool reads; in-flight write leases finish. */
export const databaseStop = tag<AbortSignal | undefined>({
  label: "database.stop",
  default: undefined,
});

export const databaseConnectTimeout = tag<number>({
  label: "database.connectTimeout",
  default: 5000,
  parse: z.number().int().positive(),
});

/** Per-statement transaction bounds also cover COMMIT and deferred constraints. */
export const databaseLockTimeout = tag<number>({
  label: "database.lockTimeout",
  default: 500,
  parse: z.number().int().positive().max(1000),
});

export const databaseStatementTimeout = tag<number>({
  label: "database.statementTimeout",
  default: 1000,
  parse: z.number().int().positive().max(2000),
});

const migrationsFolder = "drizzle";

/** Feature code uses native PostgreSQL queries, without the driver's client field. */
export const database = resource({
  label: "database",
  depends: {
    url: databaseUrl,
    postgres,
    orm: drizzlePostgres,
    stopping: databaseStop,
    timeout: databaseConnectTimeout,
  },
  factory: async (
    { url, postgres, orm, stopping, timeout },
    { defer },
  ): Promise<Database.Handle> => {
    const { default: pg } = postgres;
    const { drizzle } = orm;

    const client = new pg.Pool({ connectionString: url.href, connectionTimeoutMillis: timeout });

    const listeners = new Set<AbortController>();

    defer(async () => {
      for (const stop of listeners) stop.abort();
      await client.end();
    });

    const reads = new Proxy(client, {
      get(target, key) {
        if (key !== "query" || !stopping) return Reflect.get(target, key, target);

        /** Native pg callback; the resource owns its client and stop listener. */
        return async function queryWithStop(...args: unknown[]) {
          stopping.throwIfAborted();

          let held: PoolClient | undefined;

          const cancelled = Promise.withResolvers<never>();

          const abort = () => {
            held?.release(true);

            held = undefined;

            cancelled.reject(stopping.reason);
          };

          stopping.addEventListener("abort", abort, { once: true });

          const work = Promise.resolve().then(async () => {
            const connection = await client.connect();

            if (stopping.aborted) {
              connection.release(true);

              throw stopping.reason;
            }
            held = connection;

            try {
              return await Reflect.apply(connection.query.bind(connection), connection, args);
            } finally {
              held?.release();

              held = undefined;
            }
          });

          try {
            return await Promise.race([work, cancelled.promise]);
          } finally {
            stopping.removeEventListener("abort", abort);
          }
        };
      },
    });

    return Object.assign(drizzle({ client: reads }), {
      async checkout(guard?: Database.QueryGuard): Promise<Database.Lease> {
        // The lease is only a handle. Its first BEGIN checks out the pool client.
        return leaseFrom<PoolClient>(client.connect.bind(client), drizzle, guard);
      },
      async listen(
        channel: string,
        heard: (payload: string) => void,
        disconnected: () => void,
        signal?: AbortSignal,
      ) {
        const topic = z
          .string()
          .regex(/^[a-z_][a-z0-9_]{0,62}$/)
          .parse(channel);

        signal?.throwIfAborted();

        const stop = new AbortController();

        const cancelled = Promise.withResolvers<never>();

        let listener: PoolClient | undefined;

        const notified = (message: { payload?: string }) => heard(message.payload ?? "");

        const abort = () => stop.abort(signal?.reason);

        listeners.add(stop);

        stop.signal.addEventListener(
          "abort",
          () => {
            listeners.delete(stop);

            signal?.removeEventListener("abort", abort);

            listener?.removeListener("notification", notified);

            listener?.removeListener("error", disconnected);

            listener?.removeListener("end", disconnected);

            listener?.release(true);

            cancelled.reject(stop.signal.reason);
          },
          { once: true },
        );

        signal?.addEventListener("abort", abort, { once: true });

        const pending = client.connect().then((connection) => {
          if (stop.signal.aborted) {
            connection.release(true);

            throw stop.signal.reason;
          }
          listener = connection;

          return connection;
        });

        try {
          await Promise.race([pending, cancelled.promise]);

          stop.signal.throwIfAborted();

          listener!.on("notification", notified);

          listener!.on("error", disconnected);

          listener!.on("end", disconnected);

          await Promise.race([listener!.query(`LISTEN ${topic}`), cancelled.promise]);

          return stop.abort.bind(stop);
        } catch (error) {
          stop.abort(error);

          throw error;
        }
      },
    });
  },
});

/** Bound how long another process may own schema migration at startup. */
export const databaseMigrationTimeout = tag<number>({
  label: "database.migrationTimeout",
  default: 5000,
  parse: z.number().int().positive().max(60000),
});

/** Stable application schema lock: ASCII TINK / MIGR, shared by every process. */
export const migrationLockKey = [1414090315, 1296648018] as const;

export const migrate = operation({
  label: "migrate",
  depends: {
    database,
    pgCore: drizzlePgCore,
    migrator: drizzleMigrator,
    orm: drizzleOrm,
    timeout: databaseMigrationTimeout,
  },
  run: async ({ database, pgCore, migrator, orm, timeout }, { clock, signal }) => {
    if (!database.checkout) throw new Error("Migration requires a dedicated connection");
    const lease = await database.checkout();
    const lock = orm.sql`SELECT pg_try_advisory_lock(${migrationLockKey[0]}, ${migrationLockKey[1]}) AS owned`;
    const deadline = clock.currentTimeMillis() + timeout;
    let broken = true;

    let released = false;

    const abort = () => {
      released = true;
      lease.release(true);
    };

    try {
      while (true) {
        signal.throwIfAborted();
        const result = z
          .object({ rows: z.array(z.object({ owned: z.boolean() })) })
          .parse(await lease.db.execute(lock));
        if (result.rows[0]!.owned) break;
        if (clock.currentTimeMillis() >= deadline) throw fail("MigrationBusy", { timeout });
        await clock.sleep(Math.min(50, deadline - clock.currentTimeMillis()), signal);
      }
      // Checkout has completed. An abort can now destroy this exact connection.
      signal.addEventListener("abort", abort, { once: true });
      signal.throwIfAborted();
      await pgCore.migrate(migrator.readMigrationFiles({ migrationsFolder }), lease.db, {
        migrationsFolder,
      });

      await lease.db.execute(
        orm.sql`SELECT pg_advisory_unlock(${migrationLockKey[0]}, ${migrationLockKey[1]})`,
      );
      broken = false;
    } finally {
      signal.removeEventListener("abort", abort);
      // Any failed migration/unlock destroys the connection and releases its lock.
      if (!released) lease.release(broken);
    }
  },
});

export const databaseSetup = extension({
  label: "database.setup",
