/** The call's session owns a lazy transaction and waits for its end before returning. */
export const transaction = resource({
  label: "database.transaction",
  target: "session",
  depends: {
    database,
    lockTimeout: databaseLockTimeout,
    statementTimeout: databaseStatementTimeout,
  },
  factory: async (
    { database, lockTimeout, statementTimeout },
    { defer },
  ): Promise<Database.SessionTransaction> => {
    if (!database.checkout) throw new Error("Database preset must supply checkout for writes");
    let state: "idle" | "open" | "committed" | "rolledBack" = "idle";
    let starting: Promise<unknown> | undefined;

    let ending: Promise<void> | undefined;

    let broken = false;

    const lease = await database.checkout({
      check() {
        if (state === "committed" || state === "rolledBack") throw fail("TransactionEnded", {});
      },
      async begin() {
        if (state === "committed" || state === "rolledBack") throw fail("TransactionEnded", {});
        if (state === "idle") {
          state = "open";

          starting = lease
            .query("BEGIN")
            .then(() => lease.query(`SET LOCAL lock_timeout = '${lockTimeout}ms'`))
            .then(() => lease.query(`SET LOCAL statement_timeout = '${statementTimeout}ms'`))
            .catch((error) => {
              broken = true;

              throw error;
            });
        }
        await starting;
      },
    });
    const tx = Object.assign(lease.db, {
      transaction() {
        throw fail("NestedTransaction", {});
      },
      commit() {
        if (state === "committed" || state === "rolledBack") return Promise.resolve();

        const opened = state === "open";
        state = "committed";

        if (!opened) return Promise.resolve();

        ending = Promise.resolve(starting)
          .then(() => lease.query("COMMIT"))
          .then(() => {})
          .catch(async (error) => {
            broken = true;

            state = "rolledBack";
            await lease.query("ROLLBACK").catch(() => {});
            throw error;
          });

        void ending.catch(() => {});

        return ending;
      },
      rollback() {
        if (state === "committed" || state === "rolledBack") return Promise.resolve();

        const opened = state === "open";
        state = "rolledBack";

        if (!opened) return Promise.resolve();

        ending = Promise.resolve(starting)
          .catch(() => {})
          .then(() => lease.query("ROLLBACK"))
          .then(() => {})
          .catch((error) => {
            broken = true;

            throw error;
          });

        void ending.catch(() => {});

        return ending;
      },
    });

    defer(async (end) => {
      try {
        if (state === "idle" || state === "open") {
          if (end.status === "success") await tx.commit();
          else await tx.rollback();
        }
        await ending;
      } finally {
        lease.release(broken);
      }
    });
    return tx;
  },
});

export type { Database } from "./types";

export { database, databaseSetup, databaseUrl, migrate, transaction } from "./database.server";

export { drizzleOrm } from "./modules";

export { databaseStop, databaseConnectTimeout } from "./database.server";

export { leaseFrom } from "./lease.server";

export { databaseLockTimeout, databaseStatementTimeout } from "./database.server";

export { databaseMigrationTimeout, migrationLockKey } from "./database.server";

import type { Database } from "./types";

/**
 * Native driver bridge shared by production and test adapters. A declaration cannot
 * own a checked-out client; the database resource owns checkout and session release.
 * @param connect - From the resource; why: acquire one client only when BEGIN queries it.
 * @param drizzle - From the lazy driver module; why: bind its database to that client.
 * @param guard - From transaction; why: reject ended queries and await lazy BEGIN.
 */
export function leaseFrom<
  C extends { query: (...args: never[]) => unknown; release(broken?: boolean): void },
>(
  connect: () => Promise<C>,
  drizzle: (options: {
    client: C;

    logger: { logQuery(query: string, params: unknown[]): void };
  }) => Database.Transaction,
  guard?: Database.QueryGuard,
): Database.Lease {
  let pending: Promise<C> | undefined;
  let connection: C | undefined;

  async function query(...args: unknown[]) {
    const client = await (pending ??= connect().then((client) => {
      connection = client;
      return client;
    }));
    return Reflect.apply(client.query, client, args);
  }

  const guardedQuery = new Proxy(query, {
    async apply(target, receiver, args) {
      await guard?.begin();
      return Reflect.apply(target, receiver, args);
    },
  });

  return {
    db: drizzle({
      client: new Proxy({} as C, {
        get(_target, key) {
          if (key === "query") return guardedQuery;
          if (!connection) {
            throw new Error(`Database client field ${String(key)} read before checkout`);
          }
          return Reflect.get(connection, key, connection);
        },
      }),
      // Reject before Drizzle wraps a driver error.
      logger: {
        logQuery(query, params) {
          guard?.check();

          guard?.logQuery?.(query, params);
        },
      },
    }),
    query,
    release: (broken) => connection?.release(broken),
  };
}

