export const replayPublic = operation({
  label: "replayPublic",
  input: readCursor,
  depends: { orm: drizzleOrm, database, principal },
  run: async ({ orm, database, principal }, { input }) => {
    const { and, asc, eq, gt } = orm;
    const events = readFeatureEvents.safeParse(
      await database
