test("sign-up commits before held worker mail and records its failed delivery", async () => {
  const accepted = Promise.withResolvers<void>();
  const sending = Promise.withResolvers<void>();
  const failed = Promise.withResolvers<void>();
  const stop = new AbortController();

  const root = createScope({
    extensions: [startRequests, authStartup],
    signal: stop.signal,
    tags: [requestBindings, tags],
    observe: {
      log: (entry) => {
        if (entry.message === "outbox.retry" && entry.level === 50) failed.resolve();
      },
    },
    presets: [
      proofDatabase,
      preset(mail, async () => ({
        send: async () => {
          sending.resolve();
          await accepted.promise;
          raise("NotificationFailed", {});
        },
      })),
    ],
  });
  await root.ready;

  onTestFinished(async () => {
    accepted.resolve();
    stop.abort();
    expect((await root.closed).status).toBe("success");
  });

  await root.ready;
  await root.run(migrate);

  const reply = root.run(handleAuth, {
    input: authRequest("sign-up/email", {
      name: "Ada",
      email: "ada@example.com",
      password: "safe-password-42",
    }),
    tags: requestHeaders(new Headers()),
  });

  expect((await reply).status).toBe(200);
  const delivery = write(root, deliverMailBatch);
  await sending.promise;

  accepted.resolve();
  expect(await delivery).toEqual({ claimed: 1, sent: 0, failed: 1 });
  await failed.promise;
});

