import { createScope } from "@tinker/core";
import { test, expect } from "vite-plus/test";

import { authStartup } from "~/components/auth/index.server";
import { authSettings } from "~/components/auth/index.server";
import { auth } from "~/components/auth/index.server";
import { openSync } from "~/components/auth/index.server";
import { migrate, databaseUrl } from "~/components/database/index.server";
import { backendStop as requestHostStop } from "~/components/requests";
import { requestStop, startRequests } from "~/components/requests";
import { backendStop } from "~/components/requests";
import { bootstrapSlot, readAccountSlot } from "~/components/sync/index.server";

import { saveProfile } from "@/demo/backend/profile.server";
import * as demo from "@/demo/index.server";

import { handleAuth } from "./presets";
import { proofDatabase, proofMail, requestHeaders } from "./presets";

const requestBindings = requestHostStop(new AbortController().signal);

const tags = [
  [bootstrapSlot(demo.bootstrap), readAccountSlot(demo.readAccount)],
  databaseUrl(new URL("postgres://proof")),
  authSettings({
    origin: "http://localhost:4318",
    secret: "test-secret-with-at-least-thirty-two-letters",
  }),
];

const account = 'event: account\ndata: {"kind":"account-change"}\n\n';

function authRequest(path: string, body: object, cookie = "") {
  return new Request(`http://localhost:4318/api/auth/${path}`, {
    method: "POST",
    headers: { "content-type": "application/json", origin: "http://localhost:4318", cookie },
    body: JSON.stringify(body),
  });
}

function cookieOf(response: Response) {
  return response.headers
    .getSetCookie()
    .map((value) => value.split(";").at(0))
    .join("; ");
}

/** A signed-up account, with the cookie of its first session and its account ID. */
async function signUp(root: ReturnType<typeof createScope>, name: string) {
  const response = await root.run(handleAuth, {
    input: authRequest("sign-up/email", {
      name,
      email: `${name}@example.com`,
      password: "safe-password-42",
    }),
    tags: requestHeaders(new Headers()),
  });
  const body = (await response.json()) as { user: { id: string } };
  return { id: body.user.id, cookie: cookieOf(response) };
}

/** A second session of an account that already exists: one more device. */
async function signIn(root: ReturnType<typeof createScope>, name: string) {
  const response = await root.run(handleAuth, {
    input: authRequest("sign-in/email", {
      email: `${name}@example.com`,
      password: "safe-password-42",
    }),
    tags: requestHeaders(new Headers()),
  });
  return cookieOf(response);
}

/** A held sync stream for one device, past its greeting. */
async function openStream(root: ReturnType<typeof createScope>, accountId: string, cookie: string) {
  const session = root.createSession({ tags: requestHeaders(new Headers({ cookie })) });
  const reader = (
    await session.run(openSync, {
      input: { cursor: { public: 0, private: { accountId, revision: 0 } } },
    })
  ).getReader();
  expect(new TextDecoder().decode((await reader.read()).value)).toBe(": connected\n\n");
  return { session, reader };
}

const text = async (read: Promise<ReadableStreamReadResult<Uint8Array>>) => {
  const { value } = await read;
  return value === undefined ? "" : new TextDecoder().decode(value);
};

/** Runs one test on a fresh root with the real auth library and a PGlite database. */
async function withRoot(run: (root: ReturnType<typeof createScope>) => Promise<void>) {
  const stop = new AbortController();
  const root = createScope({
    extensions: [startRequests, authStartup],
    signal: stop.signal,
    tags: [requestBindings, [[tags, backendStop(stop.signal), requestStop(stop.signal)]]],
    presets: [proofDatabase, proofMail],
  });
  await root.ready;
  try {
    await root.run(migrate);
    await run(root);
  } finally {
    stop.abort();
    expect((await root.closed).status).toBe("success");
  }
}

test("sign-out closes the account's open stream with the account frame", async () => {
  await withRoot(async (root) => {
    const ada = await signUp(root, "Ada");
    const { session, reader } = await openStream(root, ada.id, ada.cookie);
    const held = reader.read();

    await root.run(handleAuth, {
      input: authRequest("sign-out", {}, ada.cookie),
      tags: requestHeaders(new Headers({ cookie: ada.cookie })),
    });

    expect(await text(held)).toBe(account);
    expect((await session.close({ graceful: true })).status).toBe("success");
  });
});

test("revoking another device closes only that device's stream; this device's stream stays open", async () => {
  await withRoot(async (root) => {
    const phone = await signUp(root, "Ada");
    const laptop = { id: phone.id, cookie: await signIn(root, "Ada") };
    const phoneStream = await openStream(root, phone.id, phone.cookie);
    const laptopStream = await openStream(root, laptop.id, laptop.cookie);
    const phoneHeld = phoneStream.reader.read();
    const laptopHeld = laptopStream.reader.read();

    await root.run(handleAuth, {
      input: authRequest("revoke-other-sessions", {}, laptop.cookie),
      tags: requestHeaders(new Headers({ cookie: laptop.cookie })),
    });

    expect(await text(phoneHeld)).toBe(account);

    await root.run(saveProfile, {
      input: { executionId: crypto.randomUUID(), profile: { name: "Ada laptop" } },
      tags: requestHeaders(new Headers({ cookie: laptop.cookie })),
    });

    expect(await text(laptopHeld)).toContain("event: changes");

    await laptopStream.reader.cancel();
    await phoneStream.session.close({ graceful: true });
    await laptopStream.session.close({ graceful: true });
  });
});

test("a session the server deletes closes its account's stream", async () => {
  await withRoot(async (root) => {
    const ada = await signUp(root, "Ada");
    const { session, reader } = await openStream(root, ada.id, ada.cookie);
    const held = reader.read();

    const ctx = await (await root.resolve(auth)).$context;
    const [only] = await ctx.internalAdapter.listSessions(ada.id);
    await ctx.internalAdapter.deleteSession(only!.token);

    expect(await text(held)).toBe(account);
    expect((await session.close({ graceful: true })).status).toBe("success");
  });
});

test("deleting a user closes that account's open stream", async () => {
  await withRoot(async (root) => {
    const ada = await signUp(root, "Ada");
    const { session, reader } = await openStream(root, ada.id, ada.cookie);
    const held = reader.read();

    const ctx = await (await root.resolve(auth)).$context;
    await ctx.internalAdapter.deleteUser(ada.id);

    expect(await text(held)).toBe(account);
    expect((await session.close({ graceful: true })).status).toBe("success");
  });
});

import { createScope } from "@tinker/core";
import { expect, test } from "vite-plus/test";

import { abortReasons } from "~/components/errors";
import { accountOwner } from "~/components/sync/client/owner";
import { tabStop } from "~/components/sync/client/tab";

test("closing the tab owner uses the shared abort reason", async () => {
  const root = createScope({
    extensions: [],
    tags: tabStop(new AbortController().signal),
  });
  await root.ready;
  const first = root.resolve(accountOwner).capture().signal;
  expect((await root.close({ graceful: true })).status).toBe("success");
  expect(first.reason).toBe(abortReasons.closed);
});

test("account changes reuse one AbortError reason", async () => {
  const root = createScope({
    extensions: [],
    tags: tabStop(new AbortController().signal),
  });
  await root.ready;
  try {
    const owner = root.resolve(accountOwner);
    const first = owner.capture().signal;
    owner.reset();
    const second = owner.capture().signal;
    owner.reset();

    expect(first.reason).toBe(abortReasons.changed);
    expect(second.reason).toBe(first.reason);
    expect(first.reason.name).toBe("AbortError");
    expect(first.reason.code).toBe(20);
  } finally {
    expect((await root.close({ graceful: true })).status).toBe("success");
  }
});

import type { Resource } from "@tinker/core";
import { createScope } from "@tinker/core";
import { preset } from "@tinker/core/testing";
import { expect, test } from "vite-plus/test";

import { auth, handleAuth } from "~/components/auth/index.server";
import { authSettings, authStartup } from "~/components/auth/index.server";
import { backendStop as requestHostStop } from "~/components/requests";
import { startRequests } from "~/components/requests";

import { bindings } from "./fixtures/app.server";
import type { AuthPort } from "./fixtures/app.server";

const requestBindings = requestHostStop(new AbortController().signal);

/** The same auth descriptor, typed only to the two methods the mount uses. */
const authPort: Resource.Handle<Promise<AuthPort>> = auth;

const proofAuth = preset(authPort, async () => ({
  handler: async (request: Request) =>
    Response.json({ method: request.method, path: new URL(request.url).pathname }),
  api: { getSession: async () => null },
}));

const keys = authSettings({ origin: "https://shop.example", secret: "s".repeat(32) });

test("handleAuth hands the whole request to the auth library and returns its reply", async () => {
  const root = createScope({
    extensions: [startRequests],
    tags: [requestBindings, bindings],
    presets: [proofAuth],
  });
  await root.ready;
  const get = await root.settle(handleAuth, {
    input: new Request("http://app/api/auth/get-session"),
  });
  if (get.status !== "success") throw get;
  expect(await get.value.json()).toEqual({ method: "GET", path: "/api/auth/get-session" });

  const post = await root.settle(handleAuth, {
    input: new Request("http://app/api/auth/sign-in/email", { method: "POST", body: "{}" }),
  });
  if (post.status !== "success") throw post;
  expect(await post.value.json()).toEqual({ method: "POST", path: "/api/auth/sign-in/email" });
  expect((await root.close({ graceful: true })).status).toBe("success");
});

test("handleAuth takes only a request, and a failing auth library fails the call", async () => {
  const lost = new Error("auth store lost");
  const root = createScope({
    tags: [requestBindings, bindings],
    extensions: [startRequests],
    presets: [
      preset(authPort, async () => ({
        handler: async () => {
          throw lost;
        },
        api: { getSession: async () => null },
      })),
    ],
  });
  await root.ready;

  expect((await root.settle(handleAuth, { rawInput: "/api/auth/get-session" })).status).toBe(
    "failed",
  );
  expect(
    await root.settle(handleAuth, { input: new Request("http://app/api/auth/get-session") }),
  ).toMatchObject({ status: "failed", error: lost });
  expect((await root.close({ graceful: true })).status).toBe("success");
});

test("auth config is a typed tag and invalid config fails at binding", async () => {
  const root = createScope({ tags: keys });
  expect(root.resolve(authSettings)).toEqual({
    origin: "https://shop.example",
    secret: "s".repeat(32),
  });
  expect(() => authSettings({ origin: "ftp://shop.example", secret: "short" })).toThrow(
    expect.objectContaining({
      kind: "DataValidationFailed",
      payload: expect.objectContaining({ label: "auth.settings" }),
    }),
  );
  await root.close({ graceful: true });
});

test("with auth on, the app root does not start without the auth settings", async () => {
  const root = createScope({ extensions: [authStartup] });
  await expect(root.ready).rejects.toMatchObject({
    kind: "MissingTag",
    payload: { label: "auth.settings" },
