      ),
    ],
  });

  await root.ready;
  const feed = await root.resolve(notifications);
  await feed.subscribe();
  const refused = Promise.withResolvers<never>();
  const old = feed.share("key", () => refused.promise, cursor);

  heard("saved");
  let reads = 0;
