      preset(database, async (_deps, { defer }) => {
        const { drizzle } = await import("drizzle-orm/pglite");
        const client = await syncTemplate.clone();
        defer(() => client.close());
        return Object.assign(drizzle({ client }), {
          listen: async (
            _channel: string,
