/** Exercise the actual route with the test's owned session. */
async function answer(session: Scope.Handle, request: Request) {
  const handlers = Route.options.server!.handlers!;
  if (typeof handlers === "function") throw new Error("expected the route's POST handler");

  const handler = handlers.POST;
  if (typeof handler !== "function") throw new Error("expected a POST function");

  const response = await handler({
    request,
    context: { session, signal: request.signal },
    params: {},
    pathname: "/api/telemetry",
    next: () => {
      throw new Error("POST must answer directly");
    },
  });

  expect(response).toBeInstanceOf(Response);
  if (!(response instanceof Response)) throw new Error("POST must return a Response");
  return response;
}

const empty: Telemetry.Batch = { traces: [], logs: [] };

const tabSpan: Telemetry.Span = {
  side: "browser",
  traceId: "1".repeat(32),
  spanId: "2".repeat(16),
  flags: 1,
  name: "click",
  kind: 1,
  startTimeUnixNano: "1",
  endTimeUnixNano: "2",
  attributes: [],
  events: [],
  status: { code: 1 },
};

const browserLog = (msg: string): Telemetry.Log => ({
  time: 1,
  level: 30,
  msg,
  side: "browser",
  service: "tab",
});

/**
 * A POST to the ingest route, as a tab sends it unless a field says otherwise.
 * @param row - From a test's table; why: the one header or body that differs.
 */
function post(row: {
  url?: string;
  origin?: string;
  type?: string;
  length?: string;
  body?: string | Uint8Array<ArrayBuffer> | null;
}) {
  const headers = new Headers({
    origin: row.origin ?? "http://localhost",
    "content-type": row.type ?? "application/json; charset=utf-8",
  });
  if (row.length) headers.set("content-length", row.length);
  return new Request(row.url ?? "http://localhost/api/telemetry", {
    method: "POST",
    headers,
    body: row.body === null ? null : (row.body ?? JSON.stringify(empty)),
  });
}

