  try {
    root.run(applyBootstrap, { input: { snapshot: initial, version: 0 } });
    const client = root.resolve(syncClient);
    const waiting = root.run(send, { signal: call.signal });
    await sent.promise;

    await root.run(applyEvents, {
      input: {
