  depends: { tx: transaction, orm: drizzleOrm },
  run: async ({ tx, orm }, { input, raise }) => {
    await tx.execute(orm.sql`INSERT INTO tx_proof_child(parent_id) VALUES (${input.parentId})`);
    if (input.fail) raise("StepRefused", {});
