import { createServer, type Socket } from "node:net";

import { createScope } from "@tinker/core";
import { expect, test } from "vite-plus/test";

import { mail, smtpUrl, mailFrom, mailSendTimeout } from "~/components/mail/index.server";

test("public mail total deadline ends a slow-progress send and closes its socket", async () => {
  const sockets = new Set<Socket>();
  const peerClosed = Promise.withResolvers<void>();

  const timers = new Set<ReturnType<typeof setInterval>>();

  const server = createServer((socket) => {
    sockets.add(socket);

    socket.on("error", () => {});

    socket.on("close", () => {
      sockets.delete(socket);
      peerClosed.resolve();
    });

    socket.write("220 proof SMTP\r\n");

    socket.once("data", () => {
      const timer = setInterval(() => socket.write("250-still working\r\n"), 10);

      timers.add(timer);
    });
  });

  await new Promise<void>((resolve) => server.listen(0, "127.0.0.1", resolve));

  const address = server.address();

  if (!address || typeof address === "string") throw new Error("Expected local TCP endpoint");

  const root = createScope({
    tags: [
      smtpUrl(new URL(`smtp://127.0.0.1:${address.port}`)),
      mailFrom("proof@example.test"),
      mailSendTimeout(100),
    ],
  });

  let watchdog: ReturnType<typeof setTimeout> | undefined;

  let pending: Promise<unknown> | undefined;
  let closeWatchdog: ReturnType<typeof setTimeout> | undefined;

  try {
    await root.ready;

    const sender = await root.resolve(mail);

    pending = sender
      .send({ to: "proof@example.test", subject: "No message sent", text: "Never reaches DATA" })
      .then(
        () => "sent",
        (error) => error,
      );

    const result = await Promise.race([
      pending,
      new Promise((resolve) => {
        watchdog = setTimeout(() => resolve("outside-deadline"), 700);
      }),
    ]);

    expect(result, "mail total deadline must end slow-progress send").not.toBe("outside-deadline");

    expect(result).toBeInstanceOf(Error);

    expect(String(result)).toContain("total timeout");

    const closed =
      sockets.size === 0 ||
      (await Promise.race([
        peerClosed.promise.then(() => true),
        new Promise<boolean>((resolve) => {
          closeWatchdog = setTimeout(() => resolve(false), 500);
        }),
      ]));
    expect(closed, "active SMTP socket must close at total deadline").toBe(true);
  } finally {
    clearTimeout(watchdog);
    clearTimeout(closeWatchdog);

    for (const timer of timers) clearInterval(timer);

    for (const socket of sockets) socket.destroy();

    await root.close();

    await pending;

    await new Promise<void>((resolve) => server.close(() => resolve()));
  }
});

import { createScope } from "@tinker/core";

import { defineMain, checkClosed } from "~/base/main";
import {
  databaseSetup,
  databaseMigrationTimeout,
  databaseUrl,
  databaseStop,
  databaseConnectTimeout,
  databaseLockTimeout,
  databaseStatementTimeout,
} from "~/components/database/index.server";
import {
  mailStartup,
  smtpUrl,
  mailFrom,
  mailSendTimeout as alertMailTimeout,
  mailWorkerStop,
  mailLeaseMs,
  runMailWorker,
} from "~/components/mail/index.server";
import {
  observer,
  telemetryExport,
  telemetrySide,
  telemetryService,
  tracesUrl,
  logsUrl,
  spanHistory,
} from "~/components/telemetry/index.server";

/** All processes await the shared migration owner; the host owns stop and output. */
// oxlint-disable-next-line complexity -- Native entry keeps each typed config binding inline, as the server does.
export default defineMain(async ({ env, args, signal, stdout, stderr, exit }) => {
  if (args.length) {
    stderr.write("Usage: worker\n");
    exit(64);
    return { closed: Promise.resolve() };
  }
  try {
    const exporting = !!(env.VICTORIA_TRACES_URL || env.VICTORIA_LOGS_URL);
    const tools = createScope({
      extensions: exporting ? [telemetryExport] : [],
      tags: [
        telemetrySide("worker"),
        telemetryService(env.OTEL_SERVICE_NAME ?? "tinker-worker"),
        spanHistory(env.SPAN_HISTORY === undefined ? 32 : Number(env.SPAN_HISTORY)),
        env.VICTORIA_TRACES_URL !== undefined && tracesUrl(new URL(env.VICTORIA_TRACES_URL)),
        env.VICTORIA_LOGS_URL !== undefined && logsUrl(new URL(env.VICTORIA_LOGS_URL)),
      ],
    });
    try {
      await tools.ready;
      const observed = exporting ? tools.resolve(observer) : undefined;
      const root = createScope({
        observe: {
          ...observed,
          history: tools.resolve(spanHistory),
          log: (entry) => {
            stdout.write(`${JSON.stringify(entry)}\n`);
            observed?.log?.(entry);
          },
        },
        extensions: [databaseSetup, mailStartup],
        tags: [
          env.DATABASE_MIGRATION_TIMEOUT_MS !== undefined &&
            databaseMigrationTimeout(Number(env.DATABASE_MIGRATION_TIMEOUT_MS)),
          mailWorkerStop(signal),
          env.OUTBOX_LEASE_MS !== undefined && mailLeaseMs(Number(env.OUTBOX_LEASE_MS)),
          databaseStop(signal),
          databaseConnectTimeout(500),
          databaseLockTimeout(500),
          databaseStatementTimeout(750),
          env.OUTBOX_SMTP_TIMEOUT_MS !== undefined &&
            alertMailTimeout(Number(env.OUTBOX_SMTP_TIMEOUT_MS)),
          env.DATABASE_URL !== undefined && databaseUrl(new URL(env.DATABASE_URL)),
          env.SMTP_URL !== undefined && smtpUrl(new URL(env.SMTP_URL)),
          env.SMTP_FROM !== undefined && mailFrom(env.SMTP_FROM),
        ],
      });
      try {
        await root.ready;
        root.resolve(databaseUrl);
      } catch (error) {
        await root.close();
        throw error;
      }

      // The repeated call tag opens a child session; the root tag supplies the same stop signal.
      const closed = root
        .run(runMailWorker, { tags: [mailWorkerStop(signal)] })
        .then(
          () => root.close({ graceful: true }),
          async (error) => {
            if (signal.aborted && error === signal.reason) return root.close({ graceful: true });

            await root.close();
            exit(1, error);
          },
        )
        .then((result) => {
          if (!result) return;
          checkClosed(result);
          stdout.write("outbox worker stopped\n");
        })
        .catch((error) => {
          exit(1, error);
        })
        .finally(async () => {
          checkClosed(await tools.close({ graceful: true }));
        })
        .catch((error) => {
          exit(1, error);
        });
      return { closed };
    } catch (error) {
      await tools.close({ graceful: true });
      throw error;
    }
  } catch (error) {
    let code = 1;
    if (error && typeof error === "object") {
      if ("kind" in error && ["MissingTag", "DataValidationFailed"].includes(String(error.kind))) {
        code = 78;
      }
      if ("code" in error && error.code === "ERR_INVALID_URL") code = 78;
    }
    exit(code, error);
    return { closed: Promise.resolve() };
  }
});

