import { createServer } from "node:net";

import { createScope } from "@tinker/core";
import { preset, makeTestClock, makeTestRandom } from "@tinker/core/testing";
import { expect, test } from "vite-plus/test";

import { databaseUrl, databaseConnectTimeout } from "~/components/database/index.server";
import { deliverMailBatch, runMailWorker, outboxWake } from "~/components/mail/index.server";

test("worker connect attempts stay bounded across late end events and clock ticks", async () => {
  let accepts = 0;
  const server = createServer((socket) => {
    accepts += 1;
    socket.destroy();
  });
  await new Promise<void>((resolve) => server.listen(0, "127.0.0.1", resolve));
  const address = server.address();
  if (!address || typeof address === "string") throw new Error("Expected local TCP endpoint");

  const clock = makeTestClock();
  const stop = new AbortController();
  const delays: number[] = [];
  let attempted = Promise.withResolvers<void>();
  const root = createScope({
    signal: stop.signal,
    clock,
    random: makeTestRandom({ seed: 42 }),
    tags: [databaseUrl(new URL(`postgres://proof@127.0.0.1:${address.port}/proof`))],
    presets: [
      preset(deliverMailBatch, async () => {
        throw new Error("No claim before a connection");
      }),
    ],
    observe: {
      history: 10,
      log: (entry) => {
        if (entry.message === "outbox.reconnect") {
          delays.push(Number(entry.attributes.delay));
          attempted.resolve();
        }
      },
    },
  });

  await root.ready;
  const running = root.settle(runMailWorker, { signal: stop.signal });
  try {
    await attempted.promise;
    for (let index = 0; index < 9; index += 1) {
      // Let pg's deferred error/end events and the full promise chain run.
      await new Promise<void>((resolve) => setImmediate(resolve));
      expect(accepts).toBe(index + 1);
      const cap = Math.min(30_000, 1000 * 2 ** Math.min(index, 5));
      expect(delays[index]).toBeGreaterThanOrEqual(cap / 2);
      expect(delays[index]).toBeLessThanOrEqual(cap);

      attempted = Promise.withResolvers<void>();
      clock.advance(delays[index]! - 1);
      await new Promise<void>((resolve) => setImmediate(resolve));
      expect(accepts).toBe(index + 1);
      clock.advance(1);
      await attempted.promise;
    }
    expect(accepts).toBe(10);
    expect(new Set(delays).size).toBeGreaterThan(1);
  } finally {
    stop.abort();
    await running;
    expect((await root.closed).status).toBe("success");
    await new Promise<void>((resolve) => server.close(() => resolve()));
  }
});

test("stop interrupts a black-holed LISTEN handshake", async () => {
  const sockets = new Set<import("node:net").Socket>();

  const accepted = Promise.withResolvers<void>();

  const server = createServer((socket) => {
    sockets.add(socket);

    accepted.resolve();

    socket.on("close", () => sockets.delete(socket));
  });

  await new Promise<void>((done) => server.listen(0, "127.0.0.1", done));

  const address = server.address();

  if (!address || typeof address === "string") throw new Error("Expected TCP endpoint");

  const { mailWorkerStop } = await import("~/components/mail/index.server");

  const stopping = new AbortController();

  const root = createScope({
    tags: [
      databaseUrl(new URL(`postgres://proof@127.0.0.1:${address.port}/proof`)),
      mailWorkerStop(stopping.signal),
      databaseConnectTimeout(100),
    ],
  });

  try {
    const wake = await root.resolve(outboxWake);

    const listening = wake.listen();

    const result = listening.catch((error) => error);

    await accepted.promise;

    stopping.abort();

    expect(await result).toBe(stopping.signal.reason);

    await Promise.race([
      root.close({ graceful: true }),
      new Promise((_, reject) =>
        AbortSignal.timeout(1000).addEventListener(
          "abort",
          () => reject(new Error("stop must settle before host grace")),
          { once: true },
        ),
      ),
    ]);
  } finally {
    for (const socket of sockets) socket.destroy();

    await root.close();

    await new Promise<void>((done) => server.close(() => done()));
  }
});

import assert from "node:assert/strict";
import { randomUUID } from "node:crypto";
import { resolve } from "node:path";
import { fileURLToPath } from "node:url";

import { createScope } from "@tinker/core";
import pg from "pg";
import { createServer } from "vite-plus";

const app = fileURLToPath(new URL("..", import.meta.url));

const original = process.cwd();

const migrations = resolve(process.env.BOARD_PROOF_MIGRATION_ROOT ?? app);

const vite = await createServer({
  root: app,
  configFile: false,
  server: { middlewareMode: true, hmr: false },
  resolve: { alias: { "~": fileURLToPath(new URL("../tinker", import.meta.url)) } },
});

const { databaseUrl, databaseSetup } = await vite.ssrLoadModule(
  "/tinker/components/database/index.server.ts",
);

const connectionString =
  process.env.BOARD_DATABASE_URL ?? "postgres://issue_board@127.0.0.1:15433/postgres";

const admin = new pg.Client({ connectionString });

const name = "migration_contract_" + randomUUID().replaceAll("-", "");

const url = new URL(connectionString);
url.pathname = "/" + name;

const publisher = new pg.Client({ connectionString: url.href });

const listener = new pg.Client({ connectionString: url.href });

let root;

let count = 0;

let syncCount = 0;

let fenced = Promise.withResolvers();

try {
  await admin.connect();
  await admin.query(`CREATE DATABASE ${name}`);

  process.chdir(migrations);

  root = createScope({ extensions: [databaseSetup], tags: [databaseUrl(url)] });

  await root.ready;

  await publisher.connect();
  await listener.connect();

  const triggers = await publisher.query(
    "SELECT pg_get_triggerdef(oid) AS definition FROM pg_trigger WHERE tgrelid='mail_outbox'::regclass AND tgname='board_outbox_insert' AND tgenabled='O'",
  );

  assert.equal(
    triggers.rowCount,
    1,
    "mail migration must install its enabled notification trigger",
  );

  assert.match(
    triggers.rows[0].definition,
    /AFTER INSERT[\s\S]*REFERENCING NEW TABLE AS added[\s\S]*FOR EACH STATEMENT/,
    "mail trigger must use statement transition rows",
  );

  const fn = (
    await publisher.query(
      "SELECT pg_get_functiondef('notify_board_outbox()'::regprocedure) AS definition",
    )
  ).rows[0].definition;

  assert.match(
    fn,
    /pg_notify\('board_outbox'/,
    "mail notification function must publish board_outbox",
  );

  assert.match(
    fn,
    /IF EXISTS\s*\(SELECT 1 FROM added\)/,
    "mail function must suppress empty statement notifications",
  );

  listener.on("notification", (event) => {
    if (event.channel === "board_outbox") count++;
    else if (event.channel === "start_sync") syncCount++;
    else fenced.resolve();
  });

  await listener.query("LISTEN board_outbox; LISTEN start_sync; LISTEN migration_proof_fence");

  await publisher.query(
    "INSERT INTO mail_outbox(\"to\",subject,text,dedupe_key) SELECT 'proof@example.test','Empty','None','empty' WHERE false",
  );

  await publisher.query("SELECT pg_notify('migration_proof_fence','empty')");
  await fenced.promise;

  assert.equal(count, 0, "empty insert must not publish a mail wake");

  fenced = Promise.withResolvers();

  await publisher.query("BEGIN");

  await publisher.query(
    "INSERT INTO mail_outbox(\"to\",subject,text,dedupe_key) VALUES('proof@example.test','Rollback','None','rollback')",
  );

  await publisher.query("ROLLBACK");

  await publisher.query("SELECT pg_notify('migration_proof_fence','rollback')");
  await fenced.promise;

  assert.equal(count, 0, "rolled-back insert must not publish a mail wake");

  fenced = Promise.withResolvers();

  await publisher.query("BEGIN");

  await publisher.query(
    "INSERT INTO mail_outbox(\"to\",subject,text,dedupe_key) SELECT 'proof@example.test','Batch','None',n::text FROM generate_series(1,21) n",
  );

  assert.equal(count, 0, "mail wake must wait for COMMIT");

  await publisher.query("COMMIT");

  await publisher.query("SELECT pg_notify('migration_proof_fence','commit')");
  await fenced.promise;

  assert.equal(count, 1, "committed multi-row statement must publish one mail wake");

  const syncTrigger = await publisher.query(
    "SELECT pg_get_triggerdef(oid) AS definition FROM pg_trigger WHERE tgrelid='sync_event'::regclass AND tgname='sync_event_committed' AND tgenabled='O'",
  );
  assert.equal(syncTrigger.rowCount, 1, "sync migration must install its enabled event trigger");
  assert.match(
    syncTrigger.rows[0].definition,
    /AFTER INSERT[\s\S]*FOR EACH STATEMENT[\s\S]*start_sync_wake/,
    "sync trigger must wake after an insert statement",
  );
  const syncFunction = (
    await publisher.query(
      "SELECT pg_get_functiondef('start_sync_wake()'::regprocedure) AS definition",
    )
  ).rows[0].definition;
  assert.match(
    syncFunction,
    /pg_notify\('start_sync'/,
    "sync notification function must publish start_sync",
  );

  fenced = Promise.withResolvers();
  await publisher.query("BEGIN");
  await publisher.query(
    `INSERT INTO sync_event(stream,revision,"executionId",payload) VALUES ('proof',1,'rollback','{}')`,
  );
  await publisher.query("ROLLBACK");
  await publisher.query("SELECT pg_notify('migration_proof_fence','sync-rollback')");
  await fenced.promise;
  assert.equal(syncCount, 0, "rolled-back sync insert must publish no wake");

  fenced = Promise.withResolvers();
  await publisher.query("BEGIN");
  await publisher.query(
    `INSERT INTO sync_event(stream,revision,"executionId",payload) VALUES ('proof',1,'commit','{}'),('proof',2,'commit','{}')`,
  );
  assert.equal(syncCount, 0, "sync wake must wait for COMMIT");
  await publisher.query("COMMIT");
  await publisher.query("SELECT pg_notify('migration_proof_fence','sync-commit')");
  await fenced.promise;
  assert.equal(syncCount, 1, "committed sync batch must publish one start_sync wake");
  console.log(
    "PASS real sync migration: enabled event trigger; rollback silent; committed batch publishes one start_sync wake after COMMIT.",
  );

  console.log(
    "PASS real migration contract: enabled transition-table trigger; empty and rollback silent; committed batch wakes once, ordered by a second-channel fence.",
  );
} finally {
  process.chdir(original);

  await listener.end().catch(() => {});
  await publisher.end().catch(() => {});
  await root?.close();

  await admin.query(`DROP DATABASE IF EXISTS ${name} WITH (FORCE)`);
  await admin.end();
  await vite.close();
}

import assert from "node:assert/strict";
import { spawnSync } from "node:child_process";
import { cp, mkdtemp, readdir, readFile, writeFile, mkdir, symlink, rm } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join, resolve } from "node:path";

const directory = await mkdtemp(join(tmpdir(), "migration-contract-"));

const root = resolve(".");

try {
  for (const name of [
    "src",
    "cmds",
    "tinker",
    "drizzle",
    "package.json",
    "tsconfig.json",
    "drizzle.config.ts",
    ...(await readdir(root)).filter((name) =>
      /^vite(?:\.[^.]+)?\.config\.(ts|mts|js|mjs)$/.test(name),
    ),
  ]) {
    await cp(name, join(directory, name), { recursive: true });
  }

  await mkdir(join(directory, "scripts"));
  await cp("scripts/check-schema.mjs", join(directory, "scripts/check-schema.mjs"));

  await symlink(join(root, "node_modules"), join(directory, "node_modules"), "dir");

  const folders = (await readdir(join(directory, "drizzle"))).sort().reverse();

  let target;

  let source;

  for (const folder of folders) {
    const text = await readFile(join(directory, "drizzle", folder, "migration.sql"), "utf8");

    if (text.includes("CREATE OR REPLACE FUNCTION notify_board_outbox")) {
      target = join(directory, "drizzle", folder, "migration.sql");
      source = text;
      break;
    }
  }
  assert(target, "mail notification migration must exist");

  for (const [name, broken, reason] of [
    [
      "trigger removed",
      source.replace(
        /CREATE TRIGGER board_outbox_insert[\s\S]*?EXECUTE FUNCTION notify_board_outbox\(\);/,
        "",
      ),
      /mail migration must install its enabled notification trigger/,
    ],
    [
      "channel changed",
      source.replaceAll("'board_outbox'", "'wrong_outbox'"),
      /mail notification function must publish board_outbox/,
    ],
    [
      "empty guard removed",
      source.replace(/IF EXISTS\s*\(SELECT 1 FROM added\) THEN/, "").replace("END IF;", ""),
      /mail function must suppress empty statement notifications/,
    ],
  ]) {
    assert.notEqual(broken, source, name);
    await writeFile(target, broken);

    const schema = spawnSync(process.execPath, [join(directory, "scripts/check-schema.mjs")], {
      cwd: directory,
      encoding: "utf8",
      timeout: 30000,
    });

    assert.equal(schema.status, 0, schema.stdout + schema.stderr);

    const bad = spawnSync(process.execPath, ["maintain/proof-migration-contract.mjs"], {
      encoding: "utf8",
      timeout: 30000,
      env: { ...process.env, BOARD_PROOF_MIGRATION_ROOT: directory },
    });

    assert.equal(bad.error, undefined, bad.stdout + bad.stderr);
    assert.equal(bad.status, 1, bad.stdout + bad.stderr);
    assert.match(bad.stderr, reason);

    console.log(
      "PASS migration contract control: schema-only accepts " +
        name +
        "; real migration gate rejects its named contract.",
    );
  }
  await writeFile(target, source);

  const syncTarget = join(
    directory,
    "drizzle",
    "20261002110319_sync_notifications",
    "migration.sql",
  );

  const syncSource = await readFile(syncTarget, "utf8");
  for (const [name, broken, reason] of [
    [
      "sync trigger removed",
      syncSource.replace(
        /CREATE TRIGGER sync_event_committed[\s\S]*?EXECUTE FUNCTION start_sync_wake\(\);/,
        "",
      ),
      /sync migration must install its enabled event trigger/,
    ],
    [
      "sync channel changed",
      syncSource.replaceAll("'start_sync'", "'wrong_sync'"),
      /sync notification function must publish start_sync/,
    ],
  ]) {
    assert.notEqual(broken, syncSource, name);

    await writeFile(syncTarget, broken);

    const schema = spawnSync(process.execPath, [join(directory, "scripts/check-schema.mjs")], {
      cwd: directory,
      encoding: "utf8",
      timeout: 30000,
    });
    assert.equal(schema.status, 0, schema.stdout + schema.stderr);

    const bad = spawnSync(process.execPath, ["maintain/proof-migration-contract.mjs"], {
      encoding: "utf8",
      timeout: 30000,
      env: { ...process.env, BOARD_PROOF_MIGRATION_ROOT: directory },
    });
    assert.equal(bad.error, undefined, bad.stdout + bad.stderr);

    assert.equal(bad.status, 1, bad.stdout + bad.stderr);

    assert.match(bad.stderr, reason);

    console.log(
      "PASS migration contract control: " + name + " rejected by its named sync contract.",
    );
  }
} finally {
  await rm(directory, { recursive: true, force: true });
}

import { expect, test } from "vite-plus/test";

// oxlint-disable-next-line import/no-relative-parent-imports -- Test the actual native command input and startup contract.
import main from "../cmds/worker";

for (const key of ["VICTORIA_TRACES_URL", "VICTORIA_LOGS_URL"] as const) {
  test(`worker requires the matching collector URL when only ${key} is bound`, async () => {
    const codes: number[] = [];

    let reason: unknown;

    const worker = await main({
      env: { [key]: "http://127.0.0.1:19123/collector" },
      args: [],
      signal: new AbortController().signal,
      stdout: { write() {} },
      stderr: { write() {} },
      exit(code, error) {
        codes.push(code);

        reason = error;
      },
    });

    await worker.closed;

    expect(codes).toEqual([78]);

    expect(reason).toMatchObject({
      kind: "MissingTag",
      payload: {
        label: key === "VICTORIA_TRACES_URL" ? "telemetry.logsUrl" : "telemetry.tracesUrl",
      },
    });
  });
}
